<script setup lang="ts">
import { computed, ref, watch } from 'vue';
type Product={slug:string;name:string;workspace?:string};
type Group={id:string;name:string;slug:string;description:string;planned:boolean;allHref:string|null;companies:{name:string;href:string|null}[]};
const props=defineProps<{theme:string;groups:Group[];products:Product[];administrator:boolean}>();
const search=ref('');
const collapsible=computed(()=>props.theme==='disclosure');
const activeCard=ref<string|null>(null);
function toggleCard(event:MouseEvent,id:string){
 if(!collapsible.value)return;
 event.preventDefault();
 activeCard.value=activeCard.value===id?null:id;
}
const apps=[['communication','Communication'],['canteen','Canteen Order Portal'],['store','Store Order Portal'],['daymark','Daymark'],['helpdesk','Helpdesk'],['scheduly','Scheduly'],['focus-to-do','Focus To Do'],['team-learning','Team Learning & Development'],['cv-bank','CV Bank'],['time-tracker','Time Tracker'],['admin','Admin Portal'],['onboarding','Client Onboarding Portal'],['contracts','Contracts']];
const icons:Record<string,string>={communication:'M21 11a8 8 0 0 1-8 8H7l-4 3V11a8 8 0 0 1 8-8h2a8 8 0 0 1 8 8z M7 10h10 M7 14h6',canteen:'M4 3v5a3 3 0 0 0 6 0V3 M7 3v18 M18 3c-3 3-3 7-3 10h5 M20 3v18',store:'M3 4h2l3 12h11l3-9H6 M9 21h1 M17 21h1',daymark:'M5 4h14v17H5z M9 2v4 M15 2v4 M8 10h8 M8 14h8',helpdesk:'M3 14v-3a9 9 0 0 1 18 0v3 M3 11h4v7H3z M17 11h4v7h-4z',projects:'M3 4h18v16H3z M9 4v16 M15 4v16',accounts:'M5 3h14v18H5z M8 7h8 M8 12h2 M14 12h2 M8 17h2 M14 17h2','cv-bank':'M5 3h14v18H5z M9 9a3 3 0 1 0 6 0 3 3 0 0 0-6 0 M8 18c0-4 8-4 8 0',admin:'m12 3 9 4v5c0 5-9 9-9 9s-9-4-9-9V7z M8 12l3 3 5-6',hr:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-2a7 7 0 0 1 14 0v2 M18 5a3 3 0 0 1 0 6 M22 21v-2a6 6 0 0 0-4-5',crm:'M3 4h18l-7 8v7l-4 2v-9z',learning:'M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2z M12 6v15'};
const icon=(slug:string)=>icons[slug]||'M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h5';
const matches=(value:string)=>value.toLowerCase().includes(search.value.trim().toLowerCase());
const universal=computed(()=>apps.filter(([slug])=>props.products.some(p=>p.slug===slug)||(props.administrator)).map(([slug,name])=>{const product=props.products.find(p=>p.slug===slug);return {slug,name,href:slug==='admin'&&props.administrator?'/admin':product?.workspace||null};}).filter(a=>matches(a.name)));
const visibleGroups=computed(()=>props.groups.map(g=>({...g,companies:matches(g.name)?g.companies:g.companies.filter(c=>matches(c.name))})).filter(g=>matches(g.name)||g.companies.length));
watch([search,collapsible],()=>{activeCard.value=collapsible.value&&search.value.trim()?(universal.value.length?'universal':visibleGroups.value[0]?.id||null):null;});
</script>
<template>
<section class="product-directory" :class="'layout-'+theme">
<header class="pd-heading"><div><p class="pd-eyebrow">JUDIBAS / WORKSPACE</p><h1>Products</h1><p>Choose an application or open a company workspace.</p></div><label class="pd-search"><span class="sr-only">Search products or companies</span><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></svg><input v-model="search" type="search" placeholder="Search products or companies"></label></header>
<div class="pd-layout">
<component :is="collapsible?'details':'article'" v-if="universal.length" class="pd-card pd-universal" :open="collapsible?activeCard==='universal':undefined"><component :is="collapsible?'summary':'header'" class="pd-card-heading" @click="toggleCard($event,'universal')"><span class="pd-symbol"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5"/></svg></span><div><p v-if="!collapsible" class="pd-eyebrow">SHARED APPLICATIONS</p><h2>Universal Products</h2><p v-if="!collapsible">Core applications for your workspace.</p></div><svg v-if="collapsible" class="pd-expand-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></component><div class="pd-apps"><component :is="app.href?'a':'div'" v-for="app in universal" :key="app.slug" :href="app.href||undefined" class="pd-app" :class="{'pd-unavailable':!app.href}"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="icon(app.slug)"/></svg><span>{{app.name}}</span><span v-if="app.href" class="pd-arrow" aria-hidden="true">&#8250;</span><small v-else>Coming soon</small></component></div></component>
<div class="pd-workspaces"><component :is="collapsible?'details':'article'" v-for="group in visibleGroups" :key="group.id" class="pd-card" :open="collapsible?activeCard===group.id:undefined"><component :is="collapsible?'summary':'header'" class="pd-card-heading" @click="toggleCard($event,group.id)"><span class="pd-symbol"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="icon(group.slug)"/></svg></span><div><p v-if="!collapsible" class="pd-eyebrow">COMPANY WORKSPACES</p><h2>{{group.name}}</h2><p v-if="!collapsible">{{group.description}}</p></div><svg v-if="collapsible" class="pd-expand-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></component><span v-if="group.planned" class="pd-soon">Coming soon</span><div class="pd-companies"><a v-if="group.allHref" :href="group.allHref" class="pd-company pd-all"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z"/></svg><span>All companies</span></a><component :is="company.href?'a':'div'" v-for="company in group.companies" :key="company.name" :href="company.href||undefined" class="pd-company" :class="{'pd-unavailable':!company.href}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 21V7h7V3h9v18 M2 21h20 M7 10v1 M7 14v1 M14 7h3 M14 11h3 M14 15h3 M11 21V7"/></svg><span>{{company.name}}</span></component></div><p v-if="!group.companies.length" class="pd-empty">No assigned companies in this group.</p></component></div>
</div><p v-if="!universal.length&&!visibleGroups.length" class="pd-empty" role="status">No products or companies match your search.</p>
</section>
</template>
