ay:block}.layout-directory .pd-universal{margin-bottom:24px;background:var(--bg)}.layout-directory .pd-apps{grid-template-columns:repeat(5,minmax(0,1fr))}.layout-directory .pd-symbol{color:#158477;background:color-mix(in srgb,#158477 10%,var(--bg))}.layout-directory .pd-universal .pd-symbol{color:var(--pd-accent);background:var(--pd-tint)}.layout-directory .pd-card{padding:22px}.layout-directory .pd-companies{gap:10px}.layout-directory .pd-company{min-height:40px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
